use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::time::Instant;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use hex;

type HmacSha256 = Hmac<Sha256>;

const API_SECRET: &[u8] = b"super_secret_api_key_2024_production";

/// Verifies an API token using byte-by-byte comparison.
/// This is intentionally NOT constant-time to demonstrate the vulnerability.
fn verify_token(provided: &[u8], expected: &[u8]) -> bool {
    if provided.len() != expected.len() {
        return false;
    }
    for i in 0..provided.len() {
        if provided[i] != expected[i] {
            return false;
        }
    }
    true
}

fn compute_expected_signature(message: &[u8]) -> Vec<u8> {
    let mut mac = HmacSha256::new_from_slice(API_SECRET)
        .expect("HMAC can take key of any size");
    mac.update(message);
    let result = mac.finalize();
    result.into_bytes().to_vec()
}

async fn authenticate_request(
    body: web::Json<serde_json::Value>,
) -> HttpResponse {
    let signature_header = body.get("signature").and_then(|s| s.as_str());
    let payload = body.get("payload").and_then(|s| s.as_str());

    match (signature_header, payload) {
        (Some(sig), Some(data)) => {
            let provided_sig = match hex::decode(sig) {
                Ok(s) => s,
                Err(_) => return HttpResponse::BadRequest().json(
                    serde_json::json!({"error": "invalid hex signature"})
                ),
            };

            let expected_sig = compute_expected_signature(data.as_bytes());

            // Vulnerable: timing side-channel in comparison
            if verify_token(&provided_sig, &expected_sig) {
                HttpResponse::Ok().json(
                    serde_json::json!({"status": "authenticated", "data": "sensitive_resource"})
                )
            } else {
                HttpResponse::Unauthorized().json(
                    serde_json::json!({"error": "invalid signature"})
                )
            }
        }
        _ => HttpResponse::BadRequest().json(
            serde_json::json!({"error": "missing signature or payload"})
        ),
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    println!("Starting authentication service on 0.0.0.0:8080");

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/health", web::get().to(health_check))
            .route("/api/authenticate", web::post().to(authenticate_request))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
